window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5c9a14c04584d19b"]={"versions": [{"id": "FIG-5c9a14c04584d19b", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform aus der <em>TPS Manifest Specification</em>).\n</li><li><strong>Architektur-Kontext:</strong>\n<ul class=\"fig-list\"><li>Metamodellierung diagnostischer Schnittstellen zur Einbindung von <strong>SOVD</strong> (<em>Service-Oriented Vehicle Diagnostics</em>, ASAM SOVD / ISO 22900 / ISO 13400-Familie) in die AUTOSAR Adaptive Platform (ab R22-11).\n</li><li>Funktionale Einordnung: Brückenschlag zwischen dem standardisierten Adaptive-Diagnosestack (<em>Diagnostic Management</em> / SOVD-Server) und kundenspezifischen bzw. plattforminternen Sicherheits- und Authentifizierungsapplikationen über das AUTOSAR-Port-Modell.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticPortInterface</code> (Paket: <code>PortInterface</code>):</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Abstrakt (kursiv dargestellt).\n</li><li><em>Semantik:</em> Wurzelelement des AUTOSAR-Metamodells für alle typspezifischen Diagnose-Port-Interfaces (abgeleitet von <code>PortInterface</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticSovdPortInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Abstrakt (kursiv dargestellt).\n</li><li><em>Semantik:</em> Zentrale Generalisierungsklasse für alle Schnittstellen, die exklusiv im Kontext von SOVD-Diensten, -Operationen und -Sicherheitsmechanismen operieren (Spezifikationsanforderung <code>TPS_MANI_01394</code>).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticPortInterface</code> (<code>DiagnosticSovdPortInterface</code> → <code>DiagnosticPortInterface</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticSovdAuthorizationInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition für die Autorisierungsprüfung eingehender SOVD-Anfragen (z. B. Validierung von OAuth2/JSON Web Tokens, Rollen-/Rechte-Mapping für Diagnoseoperationen; Anforderung <code>TPS_MANI_01395</code>).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdProximityChallengeInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition für die Durchführung und Auswertung von Nachweisen physischer Nähe (<em>Proximity Proof / Physical Presence Challenge</em>, z. B. Betätigen der Warnblinkanlage, Bremspedal, NFC-/BLE-Token) vor Ausführung kritischer Steuer- oder Flashfunktionen via SOVD.\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong>Kardinalitäten / Beziehungen:</strong>\n<ul class=\"fig-list\"><li>Ausschließlich unvollständige, disjunkte Generalisierungshierarchien (UML-Vererbungspfeile mit geschlossener, leerer Spitze). Keine direkten Aggregationen oder Assoziationen im abgebildeten Ausschnitt.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um einen statischen Metamodell-Ausschnitt handelt, leitet sich das dynamische Laufzeitverhalten aus den typisierten Ports ab:</p>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Eingehender SOVD-Request (HTTP/REST/WebDAV/WebSocket) am SOVD-Gateway bzw. Diagnostic Management Daemon.\n</li><li><strong>Autorisierungspfad (<code>DiagnosticSovdAuthorizationInterface</code>):</strong>\n<ul class=\"fig-list\"><li><em>Ablauf:</em> Der SOVD-Stack extrahiert Sicherheits-Header (z. B. Bearer Token) und initiiert einen synchronen/asynchronen Methodenaufruf über einen <code>RPortPrototype</code> (typisiert durch <code>DiagnosticSovdAuthorizationInterface</code>) zur autorisierenden Applikation (z. B. Security Manager).\n</li><li><em>Ergebnis:</em> Übergabe von Freigabeleveln bzw. Abbruch mit standardisiertem SOVD/HTTP-Fehlercode (z. B. <code>401 Unauthorized</code>, <code>403 Forbidden</code>).\n</li></ul>\n</li><li><strong>Proximity-Challenge-Pfad (<code>DiagnosticSovdProximityChallengeInterface</code>):</strong>\n<ul class=\"fig-list\"><li><em>Ablauf:</em> Vor Ausführung sicherheitskritischer Routinen initiiert der SOVD-Stack über den entsprechenden Port eine Challenge (Bereitstellung eines Challenge-Tokens oder Anforderung einer Nutzerinteraktion).\n</li><li><em>Verifikation:</em> Die angebundene Applikation überwacht Sensoren/Bedienelemente, validiert die Interaktion innerhalb eines definierten Zeitfensters (Timeout) und meldet das Ergebnis asynchron an den SOVD-Stack zurück.\n</li><li><em>Abbruchbedingung:</em> Timeout oder ungültiger Response führen zur Verweigerung der SOVD-Operationsausführung.\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Referenzen:</strong>\n<ul class=\"fig-list\"><li>Erfüllt <code>RS_MANI_00061</code> (Modellierung von Diagnose-Schnittstellen) und <code>RS_MANI_00070</code> (SOVD-Unterstützung).\n</li><li>Konkretisiert durch <code>TPS_MANI_01394</code> (abstrakte SOVD-Portbasis) und <code>TPS_MANI_01395</code> (spezialisierte Interfaces).\n</li></ul>\n</li><li><strong>Auswirkungen auf Manifest- &amp; Software-Architekten (ARXML-Design):</strong>\n<ul class=\"fig-list\"><li><code>DiagnosticSovdPortInterface</code> darf als abstrakte Klasse im AUTOSAR-Modell <strong>nicht</strong> direkt als Typ für <code>PPortPrototype</code> oder <code>RPortPrototype</code> instanziiert werden.\n</li><li>Entwickler müssen stattdessen die konkreten Spezialisierungen <code>DiagnosticSovdAuthorizationInterface</code> bzw. <code>DiagnosticSovdProximityChallengeInterface</code> verwenden.\n</li></ul>\n</li><li><strong>Codegenerierung &amp; Middleware-Vertrag:</strong>\n<ul class=\"fig-list\"><li>Bindung im Manifest führt zur Generierung der entsprechenden C++-Interfaces unter <code>ara::diag</code> bzw. den SOVD-Server-Schnittstellen des Adaptive Stacks.\n</li><li>Applikationsentwickler müssen lediglich die Verifizierungs- und Proximity-Logik implementieren; das Protokoll-Parsing (SOVD JSON/HTTP) verbleibt vollständig im Plattform-Stack.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4f7a511904579564", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform aus der <em>TPS Manifest Specification</em>).\n</li><li><strong>Architektur-Kontext:</strong>\n<ul class=\"fig-list\"><li>Metamodellierung diagnostischer Schnittstellen zur Einbindung von <strong>SOVD</strong> (<em>Service-Oriented Vehicle Diagnostics</em>, ASAM SOVD / ISO 22900 / ISO 13400-Familie) in die AUTOSAR Adaptive Platform (ab R22-11).\n</li><li>Funktionale Einordnung: Brückenschlag zwischen dem standardisierten Adaptive-Diagnosestack (<em>Diagnostic Management</em> / SOVD-Server) und kundenspezifischen bzw. plattforminternen Sicherheits- und Authentifizierungsapplikationen über das AUTOSAR-Port-Modell.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticPortInterface</code> (Paket: <code>PortInterface</code>):</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Abstrakt (kursiv dargestellt).\n</li><li><em>Semantik:</em> Wurzelelement des AUTOSAR-Metamodells für alle typspezifischen Diagnose-Port-Interfaces (abgeleitet von <code>PortInterface</code>). Im Diagrammlayout rechts von <code>DiagnosticSovdPortInterface</code> platziert.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdPortInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Abstrakt (kursiv dargestellt).\n</li><li><em>Semantik:</em> Zentrale Generalisierungsklasse für alle Schnittstellen im Kontext von SOVD-Diensten, -Operationen und -Sicherheitsmechanismen (<code>TPS_MANI_01394</code>).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticPortInterface</code> (<code>DiagnosticSovdPortInterface</code> → <code>DiagnosticPortInterface</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticSovdAuthorizationInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition zur Autorisierungsprüfung eingehender SOVD-Anfragen (z. B. Token-Validierung, Rollen- und Rechtemapping; <code>TPS_MANI_01395</code>).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdProximityChallengeInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition für die Durchführung und Verifikation physischer Anwesenheitsnachweise (<em>Proximity Proof / Physical Presence Challenge</em>).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdUpdateInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition für Update- und Software-Aktualisierungsoperationen über SOVD (z. B. Interaktion mit dem Update and Configuration Management / UCM).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdConfigurationInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition für Konfigurationsabfragen und Parametersetzungen über SOVD-Ressourcen.\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdServiceValidationInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition zur Validierung von SOVD-Service-Aufrufen und Vorbedingungen vor der Ausführung.\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdBulkDataInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition zur Übertragung großer Nutzdatenmengen (<em>Bulk Data Transfer</em>, z. B. Logdateien, Traces oder Flash-Container).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong>Kardinalitäten / Beziehungen:</strong>\n<ul class=\"fig-list\"><li>Ausschließlich disjunkte Generalisierungshierarchien (UML-Vererbungspfeile mit geschlossener, leerer Spitze) von allen 6 konkreten Interfaces zu <code>DiagnosticSovdPortInterface</code> sowie von <code>DiagnosticSovdPortInterface</code> zu <code>DiagnosticPortInterface</code>. Keine Assoziationen oder Attribute im Diagramm.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um einen statischen Metamodell-Ausschnitt handelt, leitet sich das dynamische Laufzeitverhalten aus den typisierten Ports ab:</p>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Eingehender SOVD-Request (HTTP/REST/WebDAV/WebSocket) am SOVD-Gateway bzw. Diagnostic Management Daemon.\n</li><li><strong>Autorisierungspfad (<code>DiagnosticSovdAuthorizationInterface</code>):</strong>\n<ul class=\"fig-list\"><li><em>Ablauf:</em> Der SOVD-Stack extrahiert Sicherheits-Header (z. B. Bearer Token) und initiiert einen synchronen/asynchronen Methodenaufruf über einen <code>RPortPrototype</code> (typisiert durch <code>DiagnosticSovdAuthorizationInterface</code>) zur autorisierenden Applikation (z. B. Security Manager).\n</li><li><em>Ergebnis:</em> Übergabe von Freigabeleveln bzw. Abbruch mit standardisiertem SOVD/HTTP-Fehlercode (z. B. <code>401 Unauthorized</code>, <code>403 Forbidden</code>).\n</li></ul>\n</li><li><strong>Proximity-Challenge-Pfad (<code>DiagnosticSovdProximityChallengeInterface</code>):</strong>\n<ul class=\"fig-list\"><li><em>Ablauf:</em> Vor Ausführung sicherheitskritischer Routinen initiiert der SOVD-Stack über den entsprechenden Port eine Challenge (Bereitstellung eines Challenge-Tokens oder Anforderung einer Nutzerinteraktion).\n</li><li><em>Verifikation:</em> Die angebundene Applikation überwacht Sensoren/Bedienelemente, validiert die Interaktion innerhalb eines definierten Zeitfensters (Timeout) und meldet das Ergebnis asynchron an den SOVD-Stack zurück.\n</li><li><em>Abbruchbedingung:</em> Timeout oder ungültiger Response führen zur Verweigerung der SOVD-Operationsausführung.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Relevanz:</strong>\n<ul class=\"fig-list\"><li>Erweiterung des SOVD-Metamodells in AUTOSAR R23-11 um funktionale Schnittstellen zur Abdeckung des gesamten SOVD-Funktionsumfangs (<code>Update</code>, <code>Configuration</code>, <code>ServiceValidation</code>, <code>BulkData</code>) neben den reinen Sicherheitsfunktionen.\n</li><li>Verbindliche Vorgabe für die Modellierung von SOVD-Service-Providern in Adaptive Application Design Manifesten.\n</li></ul>\n</li><li><strong>Entwickler-Hinweise:</strong>\n<ul class=\"fig-list\"><li>Jede funktionale SOVD-Teildomäne (Software-Updates via UCM, Konfiguration, Massendaten, Validierung) erhält ein dediziert typisiertes Port-Interface anstelle generischer Schnittstellen.\n</li><li>Implementierende Applikationen typisieren <code>PPortPrototype</code> bzw. <code>RPortPrototype</code> gezielt mit dem jeweiligen Interface, um vom SOVD-Server angesprochen zu werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c2b1e1e9b5d85630", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform aus der <em>TPS Manifest Specification</em>).\n</li><li><strong>Architektur-Kontext:</strong>\n<ul class=\"fig-list\"><li>Metamodellierung diagnostischer Schnittstellen zur Einbindung von <strong>SOVD</strong> (<em>Service-Oriented Vehicle Diagnostics</em>, ASAM SOVD / ISO 22900 / ISO 13400-Familie) in die AUTOSAR Adaptive Platform (ab R22-11).\n</li><li>Funktionale Einordnung: Brückenschlag zwischen dem standardisierten Adaptive-Diagnosestack (<em>Diagnostic Management</em> / SOVD-Server) und kundenspezifischen bzw. plattforminternen Sicherheits- und Authentifizierungsapplikationen über das AUTOSAR-Port-Modell.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticPortInterface</code> (Paket: <code>PortInterface</code>):</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Abstrakt (kursiv dargestellt).\n</li><li><em>Semantik:</em> Wurzelelement des AUTOSAR-Metamodells für alle typspezifischen Diagnose-Port-Interfaces (abgeleitet von <code>PortInterface</code>). Im Diagrammlayout rechts von <code>DiagnosticSovdPortInterface</code> platziert.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdPortInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Abstrakt (kursiv dargestellt).\n</li><li><em>Semantik:</em> Zentrale Generalisierungsklasse für alle Schnittstellen im Kontext von SOVD-Diensten, -Operationen und -Sicherheitsmechanismen (<code>TPS_MANI_01394</code>).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticPortInterface</code> (<code>DiagnosticSovdPortInterface</code> → <code>DiagnosticPortInterface</code>).\n</li></ul>\n</li><li><strong><code>DiagnosticSovdAuthorizationInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition zur Autorisierungsprüfung eingehender SOVD-Anfragen (z. B. Token-Validierung, Rollen- und Rechtemapping; <code>TPS_MANI_01395</code>).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdProximityChallengeInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition für die Durchführung und Verifikation physischer Anwesenheitsnachweise (<em>Proximity Proof / Physical Presence Challenge</em>).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdUpdateInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition für Update- und Software-Aktualisierungsoperationen über SOVD (z. B. Interaktion mit dem Update and Configuration Management / UCM).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdConfigurationInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition für Konfigurationsabfragen und Parametersetzungen über SOVD-Ressourcen.\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdServiceValidationInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition zur Validierung von SOVD-Service-Aufrufen und Vorbedingungen vor der Ausführung.\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdBulkDataInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Konkret.\n</li><li><em>Semantik:</em> Schnittstellendefinition zur Übertragung großer Nutzdatenmengen (<em>Bulk Data Transfer</em>, z. B. Logdateien, Traces oder Flash-Container).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code>.\n</li></ul>\n</li><li><strong>Kardinalitäten / Beziehungen:</strong>\n<ul class=\"fig-list\"><li>Ausschließlich disjunkte Generalisierungshierarchien (UML-Vererbungspfeile mit geschlossener, leerer Spitze) von allen 6 konkreten Interfaces zu <code>DiagnosticSovdPortInterface</code> sowie von <code>DiagnosticSovdPortInterface</code> zu <code>DiagnosticPortInterface</code>. Keine Assoziationen oder Attribute im Diagramm.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um einen statischen Metamodell-Ausschnitt handelt, leitet sich das dynamische Laufzeitverhalten aus den typisierten Ports ab:</p>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Eingehender SOVD-Request (HTTP/REST/WebDAV/WebSocket) am SOVD-Gateway bzw. Diagnostic Management Daemon.\n</li><li><strong>Autorisierungspfad (<code>DiagnosticSovdAuthorizationInterface</code>):</strong>\n<ul class=\"fig-list\"><li><em>Ablauf:</em> Der SOVD-Stack extrahiert Sicherheits-Header (z. B. Bearer Token) und initiiert einen synchronen/asynchronen Methodenaufruf über einen <code>RPortPrototype</code> (typisiert durch <code>DiagnosticSovdAuthorizationInterface</code>) zur autorisierenden Applikation (z. B. Security Manager).\n</li><li><em>Ergebnis:</em> Übergabe von Freigabeleveln bzw. Abbruch mit standardisiertem SOVD/HTTP-Fehlercode (z. B. <code>401 Unauthorized</code>, <code>403 Forbidden</code>).\n</li></ul>\n</li><li><strong>Proximity-Challenge-Pfad (<code>DiagnosticSovdProximityChallengeInterface</code>):</strong>\n<ul class=\"fig-list\"><li><em>Ablauf:</em> Vor Ausführung sicherheitskritischer Routinen initiiert der SOVD-Stack über den entsprechenden Port eine Challenge (Bereitstellung eines Challenge-Tokens oder Anforderung einer Nutzerinteraktion).\n</li><li><em>Verifikation:</em> Die angebundene Applikation überwacht Sensoren/Bedienelemente, validiert die Interaktion innerhalb eines definierten Zeitfensters (Timeout) und meldet das Ergebnis asynchron an den SOVD-Stack zurück.\n</li><li><em>Abbruchbedingung:</em> Timeout oder ungültiger Response führen zur Verweigerung der SOVD-Operationsausführung.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Relevanz:</strong>\n<ul class=\"fig-list\"><li>Erweiterung des SOVD-Metamodells in AUTOSAR R23-11 um funktionale Schnittstellen zur Abdeckung des gesamten SOVD-Funktionsumfangs (<code>Update</code>, <code>Configuration</code>, <code>ServiceValidation</code>, <code>BulkData</code>) neben den reinen Sicherheitsfunktionen.\n</li><li>Verbindliche Vorgabe für die Modellierung von SOVD-Service-Providern in Adaptive Application Design Manifesten.\n</li></ul>\n</li><li><strong>Entwickler-Hinweise:</strong>\n<ul class=\"fig-list\"><li>Jede funktionale SOVD-Teildomäne (Software-Updates via UCM, Konfiguration, Massendaten, Validierung) erhält ein dediziert typisiertes Port-Interface anstelle generischer Schnittstellen.\n</li><li>Implementierende Applikationen typisieren <code>PPortPrototype</code> bzw. <code>RPortPrototype</code> gezielt mit dem jeweiligen Interface, um vom SOVD-Server angesprochen zu werden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-af5ca5d00e9a6c8b", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Klassendiagramm (Metamodell-Ausschnitt der AUTOSAR Adaptive Platform aus der <em>TPS Manifest Specification</em>).\n</li><li><strong>Architektur-Kontext:</strong>\n<ul class=\"fig-list\"><li>Metamodellierung diagnostischer Schnittstellen zur Einbindung von <strong>SOVD</strong> (<em>Service-Oriented Vehicle Diagnostics</em>, ASAM SOVD / ISO 22900 / ISO 13400-Familie) in die AUTOSAR Adaptive Platform (ab R22-11).\n</li><li>Funktionale Einordnung: Brückenschlag zwischen dem standardisierten Adaptive-Diagnosestack (<em>Diagnostic Management</em> / SOVD-Server) und kundenspezifischen bzw. plattforminternen Sicherheits- und Authentifizierungsapplikationen über das AUTOSAR-Port-Modell.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticPortInterface</code> (Paket: <code>PortInterface</code>):</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Abstrakt (kursiv dargestellt).\n</li><li><em>Semantik:</em> Wurzelelement des AUTOSAR-Metamodells für alle typspezifischen Diagnose-Port-Interfaces. Wieder mittig oberhalb von <code>DiagnosticSovdPortInterface</code> angeordnet.\n</li></ul>\n</li><li><strong><code>DiagnosticSovdPortInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Abstrakt (kursiv dargestellt).\n</li><li><em>Semantik:</em> Zentrale Generalisierungsklasse für alle Schnittstellen im SOVD-Kontext.\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticPortInterface</code> über vertikalen Generalisierungspfeil nach oben.\n</li></ul>\n</li><li><strong>Direkte konkrete Spezialisierungen von <code>DiagnosticSovdPortInterface</code>:</strong>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticSovdAuthorizationInterface</code>:</strong> Konkrete Schnittstelle für Autorisierungsprüfungen (links angeordnet).\n</li><li><strong><code>DiagnosticSovdServiceValidationInterface</code>:</strong> Konkrete Schnittstelle zur Vorab-Validierung von SOVD-Service-Anfragen (links angeordnet).\n</li><li><strong><code>DiagnosticSovdProximityChallengeInterface</code>:</strong> Konkrete Schnittstelle für physische Anwesenheitsnachweise (links angeordnet).\n</li><li><strong><code>DiagnosticSovdBulkDataInterface</code>:</strong> Konkrete Schnittstelle für Massendatenübertragung (rechts angeordnet).\n</li><li><strong><code>DiagnosticSovdConfigurationInterface</code>:</strong> Konkrete Schnittstelle für SOVD-Konfigurationsdienste (rechts angeordnet).\n</li><li><strong><code>DiagnosticSovdUpdateInterface</code>:</strong> Konkrete Schnittstelle für Software-Updates via SOVD (rechts angeordnet).\n</li><li><strong><code>DiagnosticSovdOperationInterface</code>:</strong> Konkrete Schnittstelle für die Ausführung diagnostischer Operationen / Routinen über SOVD (rechts angeordnet).\n</li></ul>\n</li><li><strong><code>DiagnosticAbstractSovdContentInterface</code>:</strong>\n<ul class=\"fig-list\"><li><em>Stereotyp/Modifikator:</em> Abstrakt (kursiv dargestellt).\n</li><li><em>Semantik:</em> Abstrakte Zwischen-Metaklasse zur Generalisierung von SOVD-Inhaltsschnittstellen (<em>Content Interfaces</em>).\n</li><li><em>Vererbung:</em> Spezialisiert <code>DiagnosticSovdPortInterface</code> (mittig unterhalb angeordnet).\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>DiagnosticAbstractSovdContentInterface</code>:</strong>\n<ul class=\"fig-list\"><li><strong><code>DiagnosticSovdContentInterface</code>:</strong> Konkrete Schnittstelle zur Bereitstellung aggregierter SOVD-Inhalte und -Ressourcen.\n</li><li><strong><code>DiagnosticSovdContentElementInterface</code>:</strong> Konkrete Schnittstelle zur Bereitstellung atomarer SOVD-Inhaltselemente.\n</li></ul>\n</li><li><strong>Kardinalitäten / Beziehungen:</strong>\n<ul class=\"fig-list\"><li>Zweistufige disjunkte Generalisierungshierarchie ohne Mehrfachvererbung. Sieben konkrete Metaklassen sowie eine abstrakte Metaklasse erben direkt von <code>DiagnosticSovdPortInterface</code>; zwei konkrete Metaklassen erben von <code>DiagnosticAbstractSovdContentInterface</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Da es sich um einen statischen Metamodell-Ausschnitt handelt, leitet sich das dynamische Laufzeitverhalten aus den typisierten Ports ab:</p>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Eingehender SOVD-Request (HTTP/REST/WebDAV/WebSocket) am SOVD-Gateway bzw. Diagnostic Management Daemon.\n</li><li><strong>Autorisierungspfad (<code>DiagnosticSovdAuthorizationInterface</code>):</strong>\n<ul class=\"fig-list\"><li><em>Ablauf:</em> Der SOVD-Stack extrahiert Sicherheits-Header (z. B. Bearer Token) und initiiert einen synchronen/asynchronen Methodenaufruf über einen <code>RPortPrototype</code> (typisiert durch <code>DiagnosticSovdAuthorizationInterface</code>) zur autorisierenden Applikation (z. B. Security Manager).\n</li><li><em>Ergebnis:</em> Übergabe von Freigabeleveln bzw. Abbruch mit standardisiertem SOVD/HTTP-Fehlercode (z. B. <code>401 Unauthorized</code>, <code>403 Forbidden</code>).\n</li></ul>\n</li><li><strong>Proximity-Challenge-Pfad (<code>DiagnosticSovdProximityChallengeInterface</code>):</strong>\n<ul class=\"fig-list\"><li><em>Ablauf:</em> Vor Ausführung sicherheitskritischer Routinen initiiert der SOVD-Stack über den entsprechenden Port eine Challenge (Bereitstellung eines Challenge-Tokens oder Anforderung einer Nutzerinteraktion).\n</li><li><em>Verifikation:</em> Die angebundene Applikation überwacht Sensoren/Bedienelemente, validiert die Interaktion innerhalb eines definierten Zeitfensters (Timeout) und meldet das Ergebnis asynchron an den SOVD-Stack zurück.\n</li><li><em>Abbruchbedingung:</em> Timeout oder ungültiger Response führen zur Verweigerung der SOVD-Operationsausführung.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Normative Relevanz:</strong>\n<ul class=\"fig-list\"><li>Einführung einer differenzierten Inhalts- und Operationsmodellierung in AUTOSAR R25-11 durch <code>DiagnosticAbstractSovdContentInterface</code> mit den Spezialisierungen <code>DiagnosticSovdContentInterface</code> und <code>DiagnosticSovdContentElementInterface</code> sowie <code>DiagnosticSovdOperationInterface</code>.\n</li><li>Verfeinerte Abbildung des ASAM-SOVD-Ressourcenmodells (Entities, Content Elements, Operations) im AUTOSAR Adaptive Manifest.\n</li></ul>\n</li><li><strong>Entwickler-Hinweise:</strong>\n<ul class=\"fig-list\"><li>Für das Auslesen und Bereitstellen von SOVD-Datenstrukturen muss zwischen komplexen Inhalten (<code>DiagnosticSovdContentInterface</code>) und einzelnen Datenelementen (<code>DiagnosticSovdContentElementInterface</code>) differenziert werden.\n</li><li>Diagnostische Aktionen und Routinen, die über SOVD getriggert werden, nutzen nun das dedizierte <code>DiagnosticSovdOperationInterface</code>.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5c9a14c04584d19b", "to": "FIG-4f7a511904579564", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>DiagnosticSovdUpdateInterface</code>:</strong> Als neue Spezialisierungsklasse von <code>DiagnosticSovdPortInterface</code> hinzugefügt (Schnittstelle für SOVD-Update- und Flash-Funktionalitäten).\n</li><li><strong><code>DiagnosticSovdBulkDataInterface</code>:</strong> Als neue Spezialisierungsklasse von <code>DiagnosticSovdPortInterface</code> hinzugefügt (Schnittstelle für Massendatenübertragungen).\n</li><li><strong><code>DiagnosticSovdConfigurationInterface</code>:</strong> Als neue Spezialisierungsklasse von <code>DiagnosticSovdPortInterface</code> hinzugefügt (Schnittstelle für Konfigurations- und Parametrierdienste).\n</li><li><strong><code>DiagnosticSovdServiceValidationInterface</code>:</strong> Als neue Spezialisierungsklasse von <code>DiagnosticSovdPortInterface</code> hinzugefügt (Schnittstelle zur Vorab-Validierung von SOVD-Service-Anfragen).\n</li><li><strong><code>DiagnosticPortInterface</code>:</strong> Im Diagrammlayout von der vertikalen Anordnung oberhalb von <code>DiagnosticSovdPortInterface</code> nach rechts versetzt; Generalisierungspfeil verläuft nun horizontal nach rechts.\n</li></ul>"}, {"from": "FIG-4f7a511904579564", "to": "FIG-c2b1e1e9b5d85630", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c2b1e1e9b5d85630", "to": "FIG-af5ca5d00e9a6c8b", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>DiagnosticAbstractSovdContentInterface</code>:</strong> Als neue abstrakte Basisklasse (kursiv) eingeführt, die <code>DiagnosticSovdPortInterface</code> spezialisiert.\n</li><li><strong><code>DiagnosticSovdContentInterface</code>:</strong> Als neue konkrete Spezialisierungsklasse von <code>DiagnosticAbstractSovdContentInterface</code> hinzugefügt.\n</li><li><strong><code>DiagnosticSovdContentElementInterface</code>:</strong> Als neue konkrete Spezialisierungsklasse von <code>DiagnosticAbstractSovdContentInterface</code> hinzugefügt.\n</li><li><strong><code>DiagnosticSovdOperationInterface</code>:</strong> Als neue konkrete Spezialisierungsklasse von <code>DiagnosticSovdPortInterface</code> hinzugefügt.\n</li><li><strong><code>DiagnosticPortInterface</code>:</strong> Im Diagrammlayout von rechts wieder mittig oberhalb von <code>DiagnosticSovdPortInterface</code> angeordnet; Generalisierungspfeil verläuft wieder vertikal nach oben.\n</li><li><strong>Layout / Gruppierung:</strong> Die direkten Spezialisierungen von <code>DiagnosticSovdPortInterface</code> sind nun links und rechts flankierend angeordnet, während der neue Vererbungszweig über <code>DiagnosticAbstractSovdContentInterface</code> mittig nach unten abzweigt.\n</li></ul>"}]};
